const fs = require('fs');

function parseConfig(text) {
  // Null-prototype: config text is untrusted input, and a key named
  // `__proto__` or `constructor` must not be able to reach Object.prototype.
  const config = Object.create(null);
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    // Every entry must be `key=value`. A malformed line is rejected rather
    // than guessed at: silently dropping it hides a typo'd key behind a
    // setting that never takes effect.
    if (eq < 1) {
      throw new Error(`Malformed config on line ${i + 1}: ${trimmed}`);
    }
    config[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
  }
  return config;
}

function loadConfig(path) {
  // Read once at startup, before anything is serving: the synchronous call
  // costs nothing that matters here and keeps every caller free of a promise.
  let text;
  try {
    text = fs.readFileSync(path, 'utf8');
  } catch (err) {
    throw new Error(`Could not read config at ${path}: ${err.message}`);
  }
  return parseConfig(text);
}

module.exports = { parseConfig, loadConfig };

const path = require('path');
const { greet } = require('./utils');
const { loadConfig } = require('./config');

function main() {
  // Resolve against the package, not the caller's cwd: the CLI is normally
  // invoked from somewhere else entirely.
  const config = loadConfig(path.join(__dirname, '..', 'app.conf'));
  if (config.name === undefined) {
    throw new Error('Missing required config key: name');
  }
  console.log(greet(config.name));
}

main();

const test = require('node:test');
const assert = require('node:assert');
const path = require('path');
const { parseConfig, loadConfig } = require('../src/config');

test('parses key=value pairs', () => {
  assert.deepStrictEqual({ ...parseConfig('a=1\nb=2') }, { a: '1', b: '2' });
});

test('ignores blank lines and comment lines', () => {
  assert.deepStrictEqual({ ...parseConfig('\n# note\n\na=1\n') }, { a: '1' });
});

test('trims surrounding whitespace from keys and values', () => {
  assert.deepStrictEqual({ ...parseConfig('  a  =  1  ') }, { a: '1' });
});

test('handles CRLF line endings', () => {
  assert.deepStrictEqual({ ...parseConfig('a=1\r\nb=2\r\n') }, { a: '1', b: '2' });
});

test('keeps everything after the first = as the value', () => {
  assert.deepStrictEqual({ ...parseConfig('a=b=c') }, { a: 'b=c' });
});

test('allows an empty value', () => {
  assert.deepStrictEqual({ ...parseConfig('a=') }, { a: '' });
});

test('a later duplicate key wins', () => {
  assert.deepStrictEqual({ ...parseConfig('a=1\na=2') }, { a: '2' });
});

test('rejects a line with no =, reporting its line number', () => {
  assert.throws(() => parseConfig('a=1\nDEBUG\n'), /line 2: DEBUG/);
});

test('rejects a line with an empty key', () => {
  assert.throws(() => parseConfig('=v'), /line 1/);
});

test('does not reach Object.prototype via __proto__', () => {
  const config = parseConfig('__proto__=polluted');
  assert.strictEqual(Object.getPrototypeOf(config), null);
  assert.strictEqual(config.__proto__, 'polluted');
  assert.strictEqual({}.polluted, undefined);
});

test('loadConfig reads and parses the shipped app.conf', () => {
  const config = loadConfig(path.join(__dirname, '..', 'app.conf'));
  assert.strictEqual(config.name, 'world');
  assert.strictEqual(config.DEBUG, 'true');
});

test('loadConfig names the path when the file is missing', () => {
  assert.throws(() => loadConfig('/nonexistent/app.conf'), /Could not read config at \/nonexistent\/app\.conf/);
});

