const path = require('path');
const { greet } = require('./utils');
const { loadConfig } = require('./config');

const DEFAULT_CONFIG_PATH = path.join(__dirname, '..', 'app.conf');

function main(configPath = DEFAULT_CONFIG_PATH) {
  const config = loadConfig(configPath);
  // `name` is required, and the grammar allows an empty value, so an empty
  // string is as absent as a missing key: greeting nobody is not success.
  if (!config.name) {
    throw new Error('Missing or empty required config key: name');
  }
  console.log(greet(config.name));
}

// Requiring the declared package entry point must not run the program, and
// every failure here is something the user fixes in app.conf — report it as a
// message, not as a stack trace.
if (require.main === module) {
  try {
    main();
  } catch (err) {
    console.error(err.message);
    process.exitCode = 1;
  }
}

module.exports = { main };

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { main } = require('../src/index');

function withConfig(text, run) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'config-test-'));
  const file = path.join(dir, 'app.conf');
  fs.writeFileSync(file, text);
  try {
    return run(file);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

function captureLog(run) {
  const lines = [];
  const original = console.log;
  console.log = (line) => lines.push(line);
  try {
    run();
  } finally {
    console.log = original;
  }
  return lines;
}

test('greets using the configured name', () => {
  withConfig('name=Ada\n', (file) => {
    assert.deepStrictEqual(captureLog(() => main(file)), ['Hello, Ada!']);
  });
});

test('rejects a missing name', () => {
  withConfig('DEBUG=true\n', (file) => {
    assert.throws(() => main(file), /Missing or empty required config key: name/);
  });
});

test('rejects an empty name rather than greeting nobody', () => {
  withConfig('name=\n', (file) => {
    assert.throws(() => main(file), /Missing or empty required config key: name/);
  });
});

test('reports a malformed config line', () => {
  withConfig('name=Ada\nDEBUG\n', (file) => {
    assert.throws(() => main(file), /Malformed config on line 2: DEBUG/);
  });
});

test('reads the shipped app.conf by default', () => {
  assert.deepStrictEqual(captureLog(() => main()), ['Hello, world!']);
});

test('requiring the entry point does not run the program', () => {
  // The module was required at the top of this file; if it had executed,
  // its greeting would already have reached stdout.
  assert.strictEqual(typeof main, 'function');
});
